 static Material Mat(string name,Color color,float smooth=.2f){string path=Root+"Materials/"+name+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(m==null){m=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(m,path);}m.color=color;m.SetFloat("_Smoothness",smooth);m.enableInstancing=true;EditorUtility.SetDirty(m);return m;}
 static GameObject Box(string name,Transform parent,Vector3 position,Vector3 size,Material mat,bool collision=false){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=name;if(parent!=null)g.transform.SetParent(parent,false);g.transform.localPosition=position;g.transform.localScale=size;g.GetComponent<Renderer>().sharedMaterial=mat;if(!collision)UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());return g;}
 static GameObject Cylinder(string name,Transform parent,Vector3 position,Vector3 size,Material mat){var g=GameObject.CreatePrimitive(PrimitiveType.Cylinder);g.name=name;g.transform.SetParent(parent,false);g.transform.localPosition=position;g.transform.localScale=size;g.GetComponent<Renderer>().sharedMaterial=mat;UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());return g;}
 static Mesh PinMesh(){string path=Root+"Materials/Full-size pin.asset";var existing=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(existing!=null)return existing;float[] y={0,.08f,.27f,.43f,.64f,.82f,1.02f,1.16f,1.28f,1.38f,1.42f};float[] r={.12f,.17f,.25f,.24f,.17f,.09f,.085f,.12f,.12f,.08f,.015f};int sides=20;var v=new List<Vector3>();var triangles=new List<int>();for(int row=0;row<y.Length;row++)for(int j=0;j<sides;j++){float a=j*Mathf.PI*2/sides;v.Add(new Vector3(Mathf.Cos(a)*r[row],y[row],Mathf.Sin(a)*r[row]));}for(int row=0;row<y.Length-1;row++)for(int j=0;j<sides;j++){int a=row*sides+j,b=row*sides+(j+1)%sides,c=a+sides,d=b+sides;triangles.AddRange(new[]{a,c,b,b,c,d});}int bottom=v.Count;v.Add(Vector3.zero);int top=v.Count;v.Add(new Vector3(0,1.42f,0));for(int j=0;j<sides;j++){triangles.AddRange(new[]{bottom,(j+1)%sides,j,top,(y.Length-1)*sides+j,(y.Length-1)*sides+(j+1)%sides});}var mesh=new Mesh{name="Lathed bowling pin"};mesh.SetVertices(v);mesh.SetTriangles(triangles,0);mesh.RecalculateNormals();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,path);return mesh;}
 static PhysicsMaterial PhysicsMat(string name,float friction,float bounce){string path=Root+"Materials/"+name+".asset";var p=AssetDatabase.LoadAssetAtPath<PhysicsMaterial>(path);if(p==null){p=new PhysicsMaterial(name);AssetDatabase.CreateAsset(p,path);}p.dynamicFriction=p.staticFriction=friction;p.bounciness=bounce;p.frictionCombine=PhysicsMaterialCombine.Minimum;p.bounceCombine=PhysicsMaterialCombine.Average;EditorUtility.SetDirty(p);return p;}
