 static void CreateTruck(BowlingLane lane,PhysicsMaterial contact,Material dash,Material luminous,Material steel){var root=new GameObject("Tiny truck · lane "+(lane.index+1));root.transform.position=new Vector3(lane.center-.35f,.28f,-16);var body=root.AddComponent<Rigidbody>();body.mass=12;body.centerOfMass=new Vector3(0,-.02f,0);body.interpolation=RigidbodyInterpolation.Interpolate;body.collisionDetectionMode=CollisionDetectionMode.ContinuousDynamic;body.solverIterations=12;body.maxDepenetrationVelocity=3;body.angularDamping=.25f;var box=root.AddComponent<BoxCollider>();box.size=new Vector3(.7f,.36f,1.2f);box.center=new Vector3(0,.14f,0);box.sharedMaterial=contact;var truck=root.AddComponent<BowlingTruck>();truck.body=body;truck.lane=lane;lane.truck=truck;truck.exterior=new GameObject("Exterior presentation");truck.exterior.transform.SetParent(root.transform,false);HockeyAuthoring.TruckGeometry(truck.exterior.transform,1.25f);
