 static void Stretch(RectTransform rect,Vector2 padding){rect.anchorMin=Vector2.zero;rect.anchorMax=Vector2.one;rect.offsetMin=padding;rect.offsetMax=-padding;}
 static AudioClip[] Audio(){var clips=new AudioClip[9];clips[0]=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Heat - Complete Modern UI/Audio/Click.wav");string[] names={"Truck pin","Pin clack","Delivery","Strike","Spare","Lift","Sweep","Winner"};for(int k=0;k<names.Length;k++){string path=Root+"Audio/"+names[k]+".wav";int rate=22050;float duration=k==0?.22f:k==1?.16f:k==5||k==6?.4f:.5f;int length=(int)(duration*rate);if(!File.Exists(path))using(var w=new BinaryWriter(File.Create(path))){w.Write(System.Text.Encoding.ASCII.GetBytes("RIFF"));w.Write(36+length*2);w.Write(System.Text.Encoding.ASCII.GetBytes("WAVEfmt "));w.Write(16);w.Write((short)1);w.Write((short)1);w.Write(rate);w.Write(rate*2);w.Write((short)2);w.Write((short)16);w.Write(System.Text.Encoding.ASCII.GetBytes("data"));for(int i=0;i<length;i++){double t=(double)i/rate;double hz=k==0?180:k==1?420:k==5?120:k==6?90:k==3?660:440;double envelope=Math.Min(1,t*100)*Math.Min(1,(duration-t)*40)*Math.Exp(-t*(k<2?20:2));double sample=(Math.Sin(t*hz*Math.PI*2)+.3*Math.Sin(t*hz*1.51*Math.PI*2))*.3*envelope;w.Write((short)(sample*short.MaxValue));}}AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var importer=(AudioImporter)AssetImporter.GetAtPath(path);var settings=importer.defaultSampleSettings;settings.loadType=AudioClipLoadType.DecompressOnLoad;settings.compressionFormat=AudioCompressionFormat.PCM;importer.defaultSampleSettings=settings;importer.forceToMono=true;importer.SaveAndReimport();clips[k+1]=AssetDatabase.LoadAssetAtPath<AudioClip>(path);}return clips;}
 public static void UpgradeFront(){var scene=EditorSceneManager.OpenScene(SportsBuilder.FrontScene);var front=UnityEngine.Object.FindAnyObjectByType<SportsFrontEnd>();var page=front.pages[1].transform;string[] cardNames={"BILLIARDS Sport Card","HOCKEY Sport Card"};for(int i=0;i<2;i++){var card=page.Find(cardNames[i]);var rect=card.GetComponent<RectTransform>();rect.sizeDelta=new Vector2(420,520);rect.anchoredPosition=new Vector2(i==0?-450:0,-45);card.Find("Sport").GetComponent<RectTransform>().sizeDelta=new Vector2(395,70);var description=card.Find("Description").GetComponent<TMP_Text>();description.rectTransform.sizeDelta=new Vector2(385,155);description.fontSizeMax=22;description.fontSizeMin=18;if(i==1)card.Find("Rink icon").localScale=new Vector3(.8f,1,1);}
