 public static void Validate(){BowlingFixtures.Run();var scene=EditorSceneManager.OpenScene(Scene);foreach(var root in scene.GetRootGameObjects())foreach(var t in root.GetComponentsInChildren<Transform>(true))if(GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject)>0)throw new Exception("Bowling missing script: "+t.name);var m=UnityEngine.Object.FindAnyObjectByType<BowlingMatch>();if(m==null||m.lanes.Length!=4||m.setup.players.Length!=8||m.menus.names.Length!=8||m.menus.cells.Length!=80||m.feedback.clips.Length!=9||m.feedback.clips.Any(c=>c==null))throw new Exception("Bowling references incomplete");if(UnityEngine.Object.FindObjectsByType<AudioListener>(FindObjectsInactive.Include).Length!=1||UnityEngine.Object.FindObjectsByType<UnityEngine.EventSystems.EventSystem>(FindObjectsInactive.Include).Length!=1)throw new Exception("Bowling listener / EventSystem invalid");foreach(var lane in m.lanes){if(lane.pins.Length!=10||lane.truck.wheels.Length!=4||lane.cab.view.orthographic||lane.truck.engine.clip==null||lane.truck.skid.clip==null)throw new Exception("Bowling lane incomplete");foreach(var pin in lane.pins)if(pin.body==null||!pin.GetComponent<MeshCollider>().convex)throw new Exception("Bowling pin collision missing");}Debug.Log("BOWLING_SAVED_SCENE_VALIDATED");}
 static void AddInteriorLights(){for(int lane=0;lane<4;lane++)for(int segment=0;segment<4;segment++){string name="Interior lane light "+lane+"-"+segment;if(GameObject.Find(name)!=null)continue;var light=new GameObject(name).AddComponent<Light>();light.type=LightType.Point;light.intensity=18;light.range=22;light.shadows=LightShadows.None;light.color=new Color(1,.94f,.84f);light.transform.position=new Vector3(lane*7.4f,4,-10+segment*22);}}
 public static void LightAndBuild(){var scene=EditorSceneManager.OpenScene(Scene);AddInteriorLights();foreach(var text in UnityEngine.Object.FindObjectsByType<TextMeshPro>(FindObjectsInactive.Include))if(text.name=="Lane number")text.transform.rotation=Quaternion.identity;EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();LWS.TruckSports.Editor.SportsBuilder.Build();}
